SELECT *
FROM students
WHERE age > 20 AND department = 'Computer Science';

SELECT name, age
FROM students
ORDER BY age DESC;

SELECT department, COUNT(*)
FROM employees
GROUP BY department;

SELECT name, salary
FROM employees
WHERE salary > (
  SELECT AVG(salary)
  FROM employees
);

UPDATE students
SET age = 22
WHERE id = 1;

CREATE TABLE students (
  id INT PRIMARY KEY,
  email VARCHAR(100) UNIQUE NOT NULL,
  department_id INT
);
